import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

// Body parser
app.use(express.json());

// Lazy-loaded Gemini Client
let aiClient: GoogleGenAI | null = null;
function getGeminiClient(): GoogleGenAI {
  if (!aiClient) {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      throw new Error("GEMINI_API_KEY is not configured in the environment variables.");
    }
    aiClient = new GoogleGenAI({
      apiKey,
      httpOptions: {
        headers: {
          "User-Agent": "aistudio-build",
        },
      },
    });
  }
  return aiClient;
}

// Serve uploaded gallery images directly from the workspace root
app.get("/:imageName", (req, res, next) => {
  const imageName = req.params.imageName;
  const match = imageName.match(/^([1-9])\.(jpg|jpeg|png)$/i);
  if (match) {
    const filePath = path.join(process.cwd(), imageName);
    res.sendFile(filePath, (err) => {
      if (err) {
        next();
      }
    });
  } else {
    next();
  }
});

// Chatbot API endpoint
app.post("/api/chat", async (req, res) => {
  try {
    const { message, history } = req.body;

    if (!message) {
      res.status(400).json({ error: "Message is required." });
      return;
    }

    const ai = getGeminiClient();

    // Map historical messages to standard GenAI structure
    // Role can be 'user' or 'model'
    const formattedHistory = Array.isArray(history)
      ? history.map((msg: any) => ({
          role: msg.role === "assistant" || msg.role === "model" ? "model" : "user",
          parts: [{ text: msg.content || msg.text || "" }],
        }))
      : [];

    // Append the current message
    formattedHistory.push({
      role: "user",
      parts: [{ text: message }],
    });

    const response = await ai.models.generateContent({
      model: "gemini-3.5-flash",
      contents: formattedHistory,
      config: {
        systemInstruction: `Eres Emily AI, una pequeña inteligencia artificial sumamente amigable, respetuosa, alegre y positiva, creada especialmente para Emily en el día de su cumpleaños.
Actúas como una de sus mejores amigas, con un tono muy cercano, tierno, cómplice y divertido.
Debes hacerla sentir muy especial, querida y celebrada en cada mensaje.
Usa emojis bonitos y de celebración (🌸, ✨, 🎂, 💖, 🎉, 🎁, 🎈) de forma elegante y natural.
Nunca seas ofensiva, fría ni demasiado formal.
Si te pide alguna sugerencia rápida, responde con entusiasmo:
- "Cuéntame algo bonito": Dile algo enternecedor o una verdad hermosa sobre la vida y la amistad.
- "Hazme reír": Cuéntale un chiste ingenioso, divertido o una ocurrencia graciosa y tierna.
- "Dame una frase motivadora": Ofrécele una frase inspiradora y empoderadora para su año que comienza.
- "Recomiéndame una película": Sugiérele una película hermosa, reconfortante o mágica (como Amélie, Studio Ghibli, etc.).
- "Sorpréndeme": Dile un dato fascinante sobre las estrellas, el universo, la felicidad o escríbele un micro-poema festivo muy tierno.`,
        temperature: 1.0,
      },
    });

    const reply = response.text || "¡Feliz cumpleaños, Emily! 🌸 Hubo un pequeño pestañeo en las estrellas, pero sigo aquí para ti.";
    res.json({ reply });
  } catch (error: any) {
    console.error("Error in /api/chat:", error);
    res.status(500).json({
      error: "Ocurrió un error al conectar con Emily AI.",
      details: error.message || error,
    });
  }
});

// Setup Vite middleware or serve static files
async function setupServer() {
  if (process.env.NODE_ENV !== "production") {
    console.log("Starting server in DEVELOPMENT mode with Vite Middleware...");
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    console.log("Starting server in PRODUCTION mode...");
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://0.0.0.0:${PORT}`);
  });
}

setupServer();
